                for q in it[1:5]: pts.append((q.x,q.y))
pts=np.array(pts)
x0=317.75; sx=(354.95-317.75)/2.0   # "0" and "+2" labels, no minus glyphs
y0=3.75; sy=(221.2-3.75)/8.0
lm=(pts[:,0]-x0)/sx; lc=-(pts[:,1]-y0)/sy
bins=np.linspace(lm.min(),lm.max(),260)
idx=np.digitize(lm,bins)
env=[]
for i in range(1,len(bins)):
    sel=idx==i
    if sel.sum(): env.append(((bins[i-1]+bins[i])/2, lc[sel].min()))
env=np.array(env)
hbarc=1.97327e-7; Rs,R,gamma=0.61,0.76,3.3e-10
def chi(m):
    mt=m/hbarc
    h=(np.exp(-mt*(R-Rs))-np.exp(-mt*(R+Rs)))/(2*mt*Rs)
    g=(1-np.exp(-2*mt*R))/(2*mt*R)
    den=(1-gamma)*g-h
    return np.sqrt(gamma/np.where(den>0,den,np.nan))
for row in env[::15]:
